classDiagram
    class Subject {
        +string name
        +string kind
        +string namespace
    }

    class RoleBinding {
        +string name
        +string namespace
        +Subject[] subjects
        +RoleRef roleRef
    }

    class ClusterRoleBinding {
        +string name
        +Subject[] subjects
        +RoleRef roleRef
    }

    class RoleRef {
        +string kind
        +string name
        +string apiGroup
    }

    class Role {
        +string name
        +string namespace
        +PolicyRule[] rules
    }

    class ClusterRole {
        +string name
        +PolicyRule[] rules
    }

    class PolicyRule {
        +string[] apiGroups
        +string[] resources
        +string[] verbs
        +string[] resourceNames
    }

    Subject --> RoleBinding : bound by
    RoleBinding --> RoleRef : references
    RoleRef --> Role : points to
    RoleRef --> ClusterRole : points to
    Role --> PolicyRule : contains
    ClusterRole --> PolicyRule : contains
    Subject --> ClusterRoleBinding : bound by
    ClusterRoleBinding --> RoleRef : references
